11		"github.com/hashicorp/hcl/v2"
12		"github.com/hashicorp/hcl/v2/hclparse"
13		"github.com/hashicorp/hcl/v2/hclsyntax"
14	
15		"github.com/immuta/operations/apps/birdseye/internal/archive"
16	)
17	
18	// ErrParseFailed is returned by Semantic when any .tf file fails to
19	// parse. Callers map this to exit code 5.
20	var ErrParseFailed = errors.New("hcl parse failed")
21	
22	// blockEntry pairs an HCL block with the source bytes of its file so
23	// that blockHash can read actual expression text rather than byte offsets.
24	type blockEntry struct {
25		block *hclsyntax.Block
26		src   []byte
27	}
28	
29	// ModuleSummary aggregates the named HCL blocks of interest from every
30	// .tf file in a module. Maps are keyed by a stable identifier
31	// (resource: "type.name", variable: name, etc.).
32	type ModuleSummary struct {
33		Resources map[string]blockEntry
34		Variables map[string]blockEntry
35		Outputs   map[string]blockEntry
36		Providers map[string]blockEntry
37		Locals    map[string]blockEntry
38		Data      map[string]blockEntry
39		Modules   map[string]blockEntry
40	}
41	
42	// Semantic produces SemanticChange entries by parsing every .tf file in
43	// each archive into a ModuleSummary and diffing summaries.
44	func Semantic(a, b archive.Module) ([]SemanticChange, error) {
45		sa, err := summarize(a)
46		if err != nil {
47			return nil, err
48		}
49		sb, err := summarize(b)
50		if err != nil {
51			return nil, err
52		}
53		var out []SemanticChange
54		out = append(out, diffMap("resource", sa.Resources, sb.Resources)...)
55		out = append(out, diffMap("variable", sa.Variables, sb.Variables)...)
56		out = append(out, diffMap("output", sa.Outputs, sb.Outputs)...)
57		out = append(out, diffMap("provider", sa.Providers, sb.Providers)...)
58		out = append(out, diffMap("locals", sa.Locals, sb.Locals)...)
59		out = append(out, diffMap("data", sa.Data, sb.Data)...)
60		out = append(out, diffMap("module", sa.Modules, sb.Modules)...)
61		sort.SliceStable(out, func(i, j int) bool {
62			if out[i].Kind != out[j].Kind {
63				return out[i].Kind < out[j].Kind
64			}
65			return out[i].Name < out[j].Name
66		})
67		return out, nil
68	}
69	
70	func summarize(m archive.Module) (ModuleSummary, error) {
71		s := ModuleSummary{
72			Resources: map[string]blockEntry{},
73			Variables: map[string]blockEntry{},
74			Outputs:   map[string]blockEntry{},
75			Providers: map[string]blockEntry{},
76			Locals:    map[string]blockEntry{},
77			Data:      map[string]blockEntry{},
78			Modules:   map[string]blockEntry{},
79		}
80		parser := hclparse.NewParser()
81		for path, body := range m.Files {
82			if !strings.HasSuffix(path, ".tf") {
83				continue
84			}
85			file, diags := parser.ParseHCL(body, path)
86			if diags.HasErrors() {
87				return ModuleSummary{}, fmt.Errorf("%w: %s: %s", ErrParseFailed, path, diags.Error())
88			}
89			syntaxBody, ok := file.Body.(*hclsyntax.Body)
90			if !ok {
91				return ModuleSummary{}, fmt.Errorf("%w: %s: unexpected body type", ErrParseFailed, path)
92			}
93			for _, blk := range syntaxBody.Blocks {
94				key, target := classify(blk, &s)
95				if target == nil {
96					continue
97				}
98				target[key] = blockEntry{block: blk, src: body}
99			}
100		}
101		return s, nil
102	}
103	
104	func classify(blk *hclsyntax.Block, s *ModuleSummary) (string, map[string]blockEntry) {
105		switch blk.Type {
106		case "resource":
107			if len(blk.Labels) != 2 {
108				return "", nil
109			}
110			return blk.Labels[0] + "." + blk.Labels[1], s.Resources
111		case "data":
112			if len(blk.Labels) != 2 {
113				return "", nil
114			}
115			return blk.Labels[0] + "." + blk.Labels[1], s.Data
116		case "module":
117			if len(blk.Labels) != 1 {
118				return "", nil
119			}
120			return blk.Labels[0], s.Modules
121		case "variable":
122			if len(blk.Labels) != 1 {
123				return "", nil
124			}
125			return blk.Labels[0], s.Variables
126		case "output":
127			if len(blk.Labels) != 1 {
128				return "", nil
129			}
130			return blk.Labels[0], s.Outputs
131		case "provider":
132			if len(blk.Labels) != 1 {
133				return "", nil
134			}
135			return blk.Labels[0], s.Providers
136		case "locals":
137			// `locals` has no labels and may appear in multiple files;
138			// distinguish by source range so we don't collide.
139			return blk.Range().Filename + "#" + fmt.Sprint(blk.Range().Start.Line), s.Locals
140		}
141		return "", nil
142	}
